    if (fd < 0) return 0;
    for (;;) {
        i64 r = sys_read((int)fd, dst + got, cap - 1 - got);
        if (r <= 0) break;
        got += (u64)r;
        if (got >= cap - 1) break;
    }
    sys_close((int)fd);
    dst[got] = 0;
    return got;
